using UnityEngine;
using Unity.MLAgents;
using Unity.MLAgents.Actuators;
using Unity.MLAgents.Sensors;

public class PlayerAgent : Agent
{
[SerializeField] private float moveSpeed = 5.0f;
[SerializeField] private float maxEpisodeTime = 20.0f;
private TrainingArea trainingArea;
private float episodeTime = 0.0f;

public override void Initialize()
{
trainingArea = GetComponentInParent<TrainingArea>();
}

public override void OnEpisodeBegin()
{
trainingArea.ResetArea();
episodeTime = 0.0f;
}

public override void CollectObservations(VectorSensor sensor)
{
sensor.AddObservation(transform.localPosition);
}

public override void OnActionReceived(ActionBuffers actions)
{
float moveX = Mathf.Clamp(actions.ContinuousActions[0], -1, 1);
float moveY = Mathf.Clamp(actions.ContinuousActions[1], -1, 1);

Vector3 move = new Vector3(moveX, moveY, 0) * moveSpeed * Time.fixedDeltaTime;
Vector3 newPosition = transform.position + move; // Change to position instead of localPosition

// Change the OverlapCircle to use transform.position (world space) instead of localPosition
Collider2D collider = Physics2D.OverlapCircle(transform.position + move, 0.5f, LayerMask.GetMask("Wall"));
if (collider == null || !collider.CompareTag("Wall"))
{
SetReward(-0.1f);
transform.position = newPosition; // Change to position instead of localPosition
}

// Change the OverlapCircle to use transform.position (world space) instead of localPosition
Collider2D collider2 = Physics2D.OverlapCircle(transform.position + move, 0.5f, LayerMask.GetMask("Food"));
if (collider2 != null && collider2.CompareTag("Food"))
{
// Make sure the food object is part of the current TrainingArea
if (trainingArea.GetFoodInstances().Contains(collider2.gameObject))
{
Debug.Log("OnTriggerEnter2D");
SetReward(1f);
Destroy(collider2.gameObject);
}
}
}

public override void Heuristic(in ActionBuffers actionsOut)
{
ActionSegment<float> continuousActions = actionsOut.ContinuousActions;
continuousActions[0] = Input.GetAxis("Horizontal");
continuousActions[1] = Input.GetAxis("Vertical");
}

private void FixedUpdate()
{
episodeTime += Time.fixedDeltaTime;

if (episodeTime >= maxEpisodeTime || trainingArea.AllFoodEaten())
{
EndEpisode();
}
}

}

