import java.io.;
import java.util.;

public class Floyd {

    public static void main(String[] args) throws IOException {
        Scanner scanner = new Scanner(new File(“graphfile.txt”));
        PrintWriter output = new PrintWriter(“output.txt”);

        while (scanner.hasNextLine()) {
            String problemLine = scanner.nextLine();
            if (problemLine.startsWith(“Problem”)) {
                int n = Integer.parseInt(problemLine.split(“n = “)[1]);
                scanner.nextLine(); // Skip “Amatrix:” line
                int[][] graph = new int[n][n];
                int[][] next = new int[n][n];

                // Read the matrix
                for (int i = 0; i < n; i++) {
                    String[] parts = scanner.nextLine().trim().split(”\s+”);
                    for (int j = 0; j < n; j++) {
                        graph[i][j] = Integer.parseInt(parts[j]);
                        if (i != j && graph[i][j] != 0) {
                            next[i][j] = j;
                        } else {
                            next[i][j] = -1;
                        }
                    }
                }

                // Floyd-Warshall Algorithm
                for (int k = 0; k < n; k++) {
                    for (int i = 0; i < n; i++) {
                        for (int j = 0; j < n; j++) {
                            if (graph[i][j] > graph[i][k] + graph[k][j]) {
                                graph[i][j] = graph[i][k] + graph[k][j];
                                next[i][j] = next[i][k];
                            }
                        }
                    }
                }

                // Output the results
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < n; j++) {
                        if (i != j) {
                            List<Integer> path = constructPath(i, j, next);

                            output.print(“V” + (i + 1) + " to V" + (j + 1) + ": Path: ");
                            for (int p : path) {
                                output.print((p + 1) + " “);
                            }
                            output.println(”, Length: " + graph[i][j]);
                        }
                    }
                }
            }
            output.println();
        }
        output.close();
        scanner.close();
    }

    private static List<Integer> constructPath(int i, int j, int[][] next) {
        List<Integer> path = new ArrayList<>();
        if (next[i][j] == -1) return path; // means no path
        path.add(i);
        while (i != j) {
            i = next[i][j];
            path.add(i);
        }
        return path;
    }
}
