"use server";
import { jwtVerify, SignJWT } from "jose";
import { getCookie, setCookie } from "cookies-next";
import { NextResponse } from "next/server";

const secretKey = new TextEncoder().encode(process.env.JWT_SECRET_KEY);
const accessTokenExpirationTime = "15m";
const refreshTokenExpirationTime = "7d";
function convertToPlainObject(decodedToken: any) {
  return {
    ...decodedToken.payload,
    protectedHeader: { ...decodedToken.protectedHeader },
  };
}

export async function signIn(username: string, password: string) {
  // Here you would typically validate the username and password
  // For this example, we'll just create a token
  const accessToken = await new SignJWT({ username })
    .setProtectedHeader({ alg: "HS256" })
    .setExpirationTime(accessTokenExpirationTime)
    .sign(secretKey);

  const refreshToken = await new SignJWT({ username })
    .setProtectedHeader({ alg: "HS256" })
    .setExpirationTime(refreshTokenExpirationTime)
    .sign(secretKey);

  setCookie("accessToken", accessToken, { httpOnly: true });
  setCookie("refreshToken", refreshToken, { httpOnly: true });

  const decodedToken = await jwtVerify(accessToken, secretKey);
  const plainDecodedToken = convertToPlainObject(decodedToken);
  return NextResponse.json({
    success: true,
    decodedToken: plainDecodedToken,
  });
}

export async function refreshToken() {
  const refreshToken = getCookie("refreshToken");
  if (!refreshToken) {
    return NextResponse.json(
      { message: "No refresh token found" },
      { status: 401 },
    );
  }
  try {
    const { payload } = await jwtVerify(refreshToken, secretKey);
    const newAccessToken = await new SignJWT(payload)
      .setProtectedHeader({ alg: "HS256" })
      .setExpirationTime(accessTokenExpirationTime)
      .sign(secretKey);

    setCookie("accessToken", newAccessToken, { httpOnly: true });

    const decodedToken = await jwtVerify(newAccessToken, secretKey);
    const plainDecodedToken = convertToPlainObject(decodedToken);
    return NextResponse.json({
      success: true,
      decodedToken: plainDecodedToken,
    });
  } catch (error) {
    console.error("Error refreshing token:", error); // Log error for debugging
    return NextResponse.json(
      { message: "Invalid refresh token" },
      { status: 401 },
    );
  }
}

export async function protectedAction() {
  const accessToken = getCookie("accessToken");
  if (!accessToken) {
    return NextResponse.json({ message: "Unauthorized" }, { status: 401 });
  }

  try {
    await jwtVerify(accessToken, secretKey);
    return NextResponse.json({
      success: true,
      message: "Access granted to protected resource",
    });
  } catch (error) {
    return NextResponse.json(
      { message: "Invalid refresh token" },
      { status: 401 },
    );
  }
}

