"use client";

import { useCallback, useEffect, useState } from "react";

const Test = () => {
  const [decodedToken, setDecodedToken] = useState(null) as any;
  const [refreshStatus, setRefreshStatus] = useState("Not triggered") as any;
  const [countdown, setCountdown] = useState(600);

  const apiUrl = "/api/auth";

  const handleSignIn = useCallback(async () => {
    try {
      const response = await fetch(`${apiUrl}/signin`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ username: "user", password: "password" }),
      });

      if (!response.ok)
        throw new Error(`HTTP error! status: ${response.status}`);

      const result = await response.json();
      const plainToken = {
        username: result.decodedToken.username,
        exp: result.decodedToken.exp,
        protectedHeader: result.decodedToken.protectedHeader,
      };
      setDecodedToken(plainToken);
      setRefreshStatus("Token is valid");
    } catch (err) {
      console.error("Sign-in error:", err);
    }
  }, []);

  const handleRefreshToken = useCallback(async () => {
    try {
      const response = await fetch(`${apiUrl}/refresh`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
      });

      if (!response.ok)
        throw new Error(`HTTP error! status: ${response.status}`);

      const result = await response.json();
      const plainToken = {
        username: result.decodedToken.username,
        exp: result.decodedToken.exp,
        protectedHeader: result.decodedToken.protectedHeader,
      };
      setDecodedToken(plainToken);
      setRefreshStatus("Token refreshed successfully");
      return result;
    } catch (err) {
      console.error("Refresh token error:", err);
      setRefreshStatus("Refresh failed. Please log in again.");
      throw err;
    }
  }, []);

  const trigger401Error = async () => {
    try {
      const response = await fetch(`${apiUrl}/protected`, {
        method: "GET",
        headers: {
          "Content-Type": "application/json",
        },
      });

      if (!response.ok) {
        const error: any = new Error(`HTTP error! status: ${response.status}`);
        error.status = response.status;
        throw error;
      }

      const result = await response.json();
      console.log("Protected action success:", result);
    } catch (err: any) {
      console.error("Protected action error:", err);
      if (err.status === 401 || err.status === 403) {
        try {
          await handleRefreshToken();
          // Retry the original request after successful token refresh
          await trigger401Error();
        } catch (refreshError) {
          console.error("Token refresh failed:", refreshError);
          setRefreshStatus("Refresh failed. Please log in again.");
          // Optionally, redirect to login page or show login modal
        }
      } else {
        console.error("Unexpected error:", err);
      }
    }
  };

  useEffect(() => {
    handleSignIn();
    const refreshInterval = setInterval(handleRefreshToken, 600000);
    const countdownInterval = setInterval(() => {
      setCountdown((prev) => (prev <= 0 ? 600 : prev - 1));
    }, 1000);

    return () => {
      clearInterval(refreshInterval);
      clearInterval(countdownInterval);
    };
  }, [handleSignIn, handleRefreshToken]);

  const formatCountdown = (seconds: any) => {
    const minutes = Math.floor(seconds / 60);
    const remainingSeconds = seconds % 60;
    return `${minutes}:${remainingSeconds.toString().padStart(2, "0")}`;
  };

  return (
    <div className="max-w-2xl mx-auto p-6 bg-gray-100 rounded-lg shadow-md">
      <h2 className="text-2xl font-bold mb-4">Decoded JWT:</h2>
      <pre className="bg-white p-4 rounded-md overflow-auto mb-4">
        {decodedToken
          ? JSON.stringify(decodedToken, null, 2)
          : "No token found"}
      </pre>
      <p className="mb-2">
        <span className="font-semibold">Refresh status:</span> {refreshStatus}
      </p>
      <p className="mb-4">
        <span className="font-semibold">Time until next refresh:</span>{" "}
        {formatCountdown(countdown)}
      </p>
      <button
        onClick={trigger401Error}
        className="bg-blue-500 hover:bg-blue-600 text-white font-bold py-2 px-4 rounded"
      >
        Trigger 401/403 Error
      </button>
    </div>
  );
};

export default Test;

