class Clipboard extends InputWidget
{
/**
* @var type
* Tyope of input to use
*/
public $type;

/**
* @var action
* Which action to perfom, either a cut or a simple copy
*/
public $action = 'copy';

/**
* @ignore
*/
const CUT = 'cut';
const COPY = 'copy';

public function run()//: ?string
{
return self::asHtml(
$this->getView(),
$this->type,
$this->action,
$this->attribute,
Html::getAttributeValue($this->model, $this->attribute),
$this->options
);
}

public static function input(View $view, $type, $name = null, $value = null, $options = [], $action = null): string
{
if ($action === null) {

$action = self::COPY;
}

return self::asHtml($view, $type, $action, $name, $value, $options);
}

private static function asHtml(View $view, $type, $action, $name = null, $value = null, $options = []): string
{
if (!isset($options['type'])) {

$options['type'] = $type;
}

$options['name'] = $name;
$options['value'] = $value === null ? null : (string) $value;

$id = ArrayHelper::getValue($options, 'id', false);
if ($id === false) {

$id = $name;
}

Html::addCssClass($options, 'form-control');
Html::addCssClass($options, $name);
$content = Html::tag('div',
Html::tag('div',
Html::tag('a', 'Copy', [
// Copy content from another element by adding a 'data-clipboard-target' attribute in your trigger element.
'data-clipboard-target' => '#' . $id,
// Define a 'data-clipboard-action' attribute to specify if you want to either copy or cut
'data-clipboard-action' => $action,
// Bootstrap4 secondary button
'class' => 'btn btn-outline-secondary btn-' . $id,
]),
['class' => 'input-group-prepend']) . Html::tag('input', '', $options),
['class' => 'input-group mb-3']
);

$view->registerJs("new ClipboardJS('.btn-" . $id . "')");
return $content;
}
}

