fn analyze_pool_data(&self, pool_data: &str) -> PyResult<String> {
let decoded = base64_engine.decode(pool_data)
.map_err(|e| PyValueError::new_err(e.to_string()))?;
if decoded.len() >= 592 {
let base_mint = &decoded[8..40];
let quote_mint = &decoded[40..72];
let base_reserves = u64::from_le_bytes(decoded[72..80].try_into().unwrap());
let quote_reserves = u64::from_le_bytes(decoded[80..88].try_into().unwrap());
let analysis = json!({
"base_mint": base_mint.to_vec(),
"quote_mint": quote_mint.to_vec(),
"base_reserves": base_reserves,
"quote_reserves": quote_reserves,
"price": (quote_reserves as f64) / (base_reserves as f64),
"liquidity": base_reserves + quote_reserves,
"timestamp": chrono::Utc::now().to_rfc3339()
});
Ok(serde_json::to_string(&analysis).map_err(|e| PyValueError::new_err(e.to_string()))?)
} else {
Err(PyValueError::new_err("Invalid pool data size"))
}
}

fn open_position(&self, size: f64) -> PyResult<String> {
let current_price = self.get_pool_price()?;
let quote = self.get_jupiter_quote("So11111111111111111111111111111111111111112",
"EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v",
(size * 1e9) as u64)?;
let tx = self.send_priority_transaction(&quote)?;
let position = Position {
entry_price: current_price,
size,
timestamp: Utc::now(),
tx_signature: tx.clone(),
pnl: 0.0,
status: "OPEN".to_string(),
};
let mut positions = self.positions.lock().unwrap();
positions.push_back(position);
Ok(tx)
}

fn close_position(&self, position_index: usize) -> PyResult<String> {
let mut positions = self.positions.lock().unwrap();
if let Some(position) = positions.get_mut(position_index) {
let current_price = self.get_pool_price()?;
let quote = self.get_jupiter_quote("EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v",
"So11111111111111111111111111111111111111112",
(position.size * 1e9) as u64)?;
let tx = self.send_priority_transaction(&quote)?;
position.pnl = (current_price - position.entry_price) * position.size;
position.status = "CLOSED".to_string();
Ok(tx)
} else {
Err(PyValueError::new_err("Invalid position index"))
}
}

fn get_jupiter_quote(&self, input_mint: &str, output_mint: &str, amount: u64) -> PyResult<String> {
let url = format!(
"{}/quote?inputMint={}&outputMint={}&amount={}&slippageBps=50&onlyDirectRoutes=true&asLegacyTransaction=false",
JUPITER_API_V6, input_mint, output_mint, amount
);
let quote = self.runtime.block_on(async {
reqwest::get(&url)
.await
.map_err(|e| PyValueError::new_err(e.to_string()))?
.json::<serde_json::Value>()
.await
.map_err(|e| PyValueError::new_err(e.to_string()))
})?;
Ok(serde_json::to_string(&quote).map_err(|e| PyValueError::new_err(e.to_string()))?)
}

fn send_priority_transaction(&self, transaction_data: &str) -> PyResult<String> {
let request = json!({
"jsonrpc": "2.0",
"id": "helius-priority",
"method": "sendTransaction",
"params": [
transaction_data,
{
"encoding": "base64",
"maxRetries": 0,
"skipPreflight": true,
"preflightCommitment": "confirmed",
"priorityFee": 15000
}
]
});
let response = self.runtime.block_on(async {
reqwest::Client::new()
.post(HELIUS_RPC)
.headers(self.headers.clone())
.json(&request)
.send()
.await
.map_err(|e| PyValueError::new_err(e.to_string()))?
.json::<serde_json::Value>()
.await
.map_err(|e| PyValueError::new_err(e.to_string()))
})?;
Ok(response["result"].to_string())
}

fn get_positions(&self) -> PyResult<String> {
let positions = self.positions.lock().unwrap();
let positions_json = serde_json::to_string(&*positions).map_err(|e| PyValueError::new_err(e.to_string()))?;
Ok(positions_json)
}

fn get_market_metrics(&self) -> PyResult<HashMap<String, f64>> {
let prices = self.last_prices.lock().unwrap();
let prices_vec: Vec<f64> = prices.iter().cloned().collect();
let mut metrics = HashMap::new();
if !prices_vec.is_empty() {
metrics.insert("current_price".to_string(), *prices_vec.last().unwrap());
metrics.insert("price_change".to_string(), (prices_vec.last().unwrap() - prices_vec.first().unwrap()) / prices_vec.first().unwrap());
if prices_vec.len() > 1 {
let returns: Vec<f64> = prices_vec.windows(2)
.map(|w| (w[1] - w[0]) / w[0])
.collect();
let volatility = returns.iter().map(|r| r * r).sum::<f64>().sqrt() * (252.0_f64).sqrt();
metrics.insert("volatility".to_string(), volatility);
}
}
Ok(metrics)
}
}

