impl SolanaTrader {
#[new]
fn new(config_path: String, keypair_bytes: Vec<u8>) -> PyResult<Self> {
let runtime = get_runtime()?;
let keypair = Keypair::from_bytes(&keypair_bytes)
.map_err(|e| PyValueError::new_err(format!("Invalid keypair: {}", e)))?;

let config = load_config(&config_path)
.map_err(|e| PyValueError::new_err(format!("Config error: {}", e)))?;

let http_client = Client::builder()
.timeout(Duration::from_secs(10))
.pool_max_idle_per_host(100)
.default_headers({
let mut headers = reqwest::header::HeaderMap::new();
headers.insert(
"Authorization",
format!("Bearer {}", config.network.api_key)
.parse()
.unwrap()
);
headers
})
.build()
.map_err(|e| PyValueError::new_err(format!("HTTP client error: {}", e)))?;

let rpc_client = RpcClient::new_with_commitment(
config.network.rpc_url.clone(),
CommitmentConfig::confirmed()
);

Ok(Self {
settings: Arc::new(RwLock::new(ScalperSettings::new())),
http_client: Arc::new(http_client),
rpc_client: Arc::new(rpc_client),
active_trades: Arc::new(DashMap::new()),
market_data_cache: Arc::new(DashMap::new()),
keypair: Arc::new(keypair),
runtime,
