fn get_market_data(&self, token: String) -> PyResult<MarketData> {
self.runtime.block_on(async {
let token_pubkey = Pubkey::from_str(&token)
.map_err(|e| PyValueError::new_err(format!("Invalid token address: {}", e)))?;

// Get token account info
let account_info = match self.rpc_client.get_account(&token_pubkey).await {
Ok(info) => info,
Err(e) => {
return Err(PyValueError::new_err(format!("RPC error: {}", e)));
}
};

// Get token supply
let token_supply = match self.rpc_client.get_token_supply(&token_pubkey).await {
Ok(supply) => supply,
Err(e) => {
return Err(PyValueError::new_err(format!("Token supply error: {}", e)));
}
};

// Get Jupiter price data
let jupiter_url = format!(
"https://price.jup.ag/v4/price?ids={}",
token
);

let price_data = self.http_client
.get(&jupiter_url)
.send()
.await
.map_err(|e| PyValueError::new_err(format!("Price request failed: {}", e)))?
.json::<Value>()
.await
.map_err(|e| PyValueError::new_err(format!("Price parse failed: {}", e)))?;

let market_data = MarketData {
price: price_data["data"][token]["price"]
.as_f64()
.unwrap_or_default(),
volume_24h: price_data["data"][token]["volume24h"]
.as_f64()
.unwrap_or_default(),
liquidity: token_supply.ui_amount.unwrap_or_default(),
price_change_24h: price_data["data"][token]["price_change_24h"]
.as_f64()
.unwrap_or_default(),
timestamp: SystemTime::now()
.duration_since(UNIX_EPOCH)
.unwrap_or_default()
.as_secs() as i64,
};

self.market_data_cache.insert(token, market_data.clone());
Ok(market_data)
})
}

fn get_jupiter_quote(&self, token: &str, amount: u64, is_buy: bool) -> PyResult<PyObject> {
let url = format!(
"{}/quote?inputMint={}&outputMint={}&amount={}&slippageBps=50&onlyDirectRoutes=true&wrapUnwrapSOL=true",
JUPITER_API,
if is_buy { SOL_MINT } else { token },
if is_buy { token } else { SOL_MINT },
amount
);

Python::with_gil(|py| {
self.runtime.block_on(async {
let response = self.http_client
.get(&url)
.send()
.await
.map_err(|e| PyValueError::new_err(format!("Quote request failed: {}", e)))?
.json::<Value>()
.await
.map_err(|e| PyValueError::new_err(format!("Quote parse failed: {}", e)))?;

let dict = PyDict::new(py);
dict.set_item("quoteResponse", response.to_string())?;
Ok(dict.to_object(py))
})
})
}

fn execute_jupiter_swap(&self, quote: &PyAny, token: &str, priority_fee: u64) -> PyResult<String> {
self.runtime.block_on(async {
let quote: Value = serde_json::from_str(
&quote.get_item("quoteResponse")?.extract::<String>()?
).map_err(|e| PyValueError::new_err(format!("Quote parse error: {}", e)))?;

let recent_blockhash = self.rpc_client
.get_latest_blockhash()
.await
.map_err(|e| PyValueError::new_err(format!("Failed to get blockhash: {}", e)))?;

let swap_request = json!({
"quoteResponse": quote,
"userPublicKey": self.keypair.pubkey().to_string(),
"wrapUnwrapSOL": true,
"computeUnitPriceMicroLamports": priority_fee,
"priorityFeeLamports": priority_fee,
"asLegacyTransaction": false,
"maxAccounts": 64,
"recentBlockhash": recent_blockhash.to_string()
});

let swap_response = self.http_client
.post(format!("{}/swap", JUPITER_API))
.json(&swap_request)
.send()
.await
.map_err(|e| PyValueError::new_err(format!("Swap request failed: {}", e)))?
.json::<Value>()
.await
.map_err(|e| PyValueError::new_err(format!("Swap response parse failed: {}", e)))?;

let swap_data = swap_response["swapTransaction"]
.as_str()
.ok_or_else(|| PyValueError::new_err("Invalid swap response"))?;

let helius_request = json!({
"jsonrpc": "2.0",
"id": "helius-priority",
"method": "sendTransaction",
"params": [
swap_data,
{
"encoding": "base64",
"maxRetries": 3,
"skipPreflight": true,
"preflightCommitment": "processed",
"priorityFee": priority_fee
}
]
});

let tx_response = self.http_client
.post(&self.config.network.rpc_url)
.header(
"Authorization",
format!("{}{}", HELIUS_API_HEADER, self.config.network.api_key)
)
.json(&helius_request)
.send()
.await
.map_err(|e| PyValueError::new_err(format!("Transaction send failed: {}", e)))?
.json::<Value>()
.await
.map_err(|e| PyValueError::new_err(format!("Transaction response parse failed: {}", e)))?;

match tx_response.get("result") {
Some(result) => {
let signature = result.as_str().unwrap_or_default().to_string();

// Fixed confirmation with correct parameters
match self.rpc_client
.confirm_transaction_with_spinner(
&signature.parse().unwrap(),
&recent_blockhash,
CommitmentConfig::confirmed()
).await
{
Ok(_) => {
println!("Swap executed successfully: {}", signature);
Ok(signature)
},
Err(e) => {
Err(PyValueError::new_err(format!(
"Transaction confirmation failed: {}", e
)))
}
}
},
None => {
if let Some(error) = tx_response.get("error") {
Err(PyValueError::new_err(format!(
"Helius error: {:?}", error
)))
} else {
Err(PyValueError::new_err("Unexpected response format"))
}
}
}
})
}
fn execute_trade(&self, token: String, is_buy: bool) -> PyResult<String> {
self.runtime.block_on(async {
let settings = self.settings.read().await;

// Validate trade conditions
if is_buy && self.active_trades.len() >= self.config.performance.max_concurrent_trades {
return Err(PyValueError::new_err("Maximum concurrent trades reached"));
}

// Check market conditions
if let Ok(market_data) = self.get_market_data(token.clone()) {
if is_buy {
if market_data.volume_24h < settings.min_volume {
return Err(PyValueError::new_err("Insufficient volume"));
}
if market_data.liquidity < self.config.sniping.min_liquidity {
return Err(PyValueError::new_err("Insufficient liquidity"));
}
}
}

let amount = if is_buy {
(settings.max_position_size * 1e9) as u64
} else {
match self.active_trades.get(&token) {
Some(trade) => (trade.size * 1e9) as u64,
None => return Err(PyValueError::new_err("No active trade found"))
}
};

// Execute the trade
let result = Python::with_gil(|py| -> PyResult<String> {
let quote = self.get_jupiter_quote(&token, amount, is_buy)?;
self.execute_jupiter_swap(quote.as_ref(py), &token, settings.priority_fee)
})?;

// Update trade tracking
if is_buy {
if let Ok(market_data) = self.get_market_data(token.clone()) {
self.active_trades.insert(
token.clone(),
Trade {
token,
entry_price: market_data.price,
current_price: market_data.price,
size: amount as f64 / 1e9,
profit_loss: 0.0,
timestamp: SystemTime::now()
.duration_since(UNIX_EPOCH)
.unwrap_or_default()
.as_secs() as i64,
status: "ACTIVE".to_string(),
},
);
}
} else {
// Calculate final PnL before removing trade
if let Some(trade) = self.active_trades.get(&token) {
if let Ok(market_data) = self.get_market_data(token.clone()) {
let pnl = (market_data.price - trade.entry_price) / trade.entry_price * 100.0;
println!("Trade closed with PnL: {:.2}%", pnl);
}
}
self.active_trades.remove(&token);
}

Ok(result)
})
}

fn get_active_trades(&self) -> PyResult<HashMap<String, Trade>> {
Ok(self.active_trades
.iter()
.map(|entry| (entry.key().clone(), entry.value().clone()))
.collect())
}

fn get_cached_market_data(&self, token: String) -> PyResult<MarketData> {
self.market_data_cache
.get(&token)
.map(|data| data.clone())
.ok_or_else(|| PyValueError::new_err("No cached market data found"))
}

fn update_settings(&self, new_settings: ScalperSettings) -> PyResult<()> {
self.runtime.block_on(async {
*self.settings.write().await = new_settings;
Ok(())
})
}

// Additional helper methods for risk management
fn check_risk_limits(&self, token: &str, price: f64, size: f64) -> PyResult<bool> {
let total_exposure: f64 = self.active_trades
.iter()
.map(|trade| trade.size * trade.current_price)
.sum();

let new_trade_value = price * size;
let total_with_new = total_exposure + new_trade_value;

if total_with_new > self.config.scalping.max_position_size {
return Ok(false);
}

// Check price impact
if let Ok(market_data) = self.get_market_data(token.to_string()) {
let price_impact = (price - market_data.price).abs() / market_data.price * 100.0;
if price_impact > self.config.performance.price_impact_threshold {
return Ok(false);
}
}

Ok(true)
}

// Method to update trade status and PnL
fn update_trade_status(&self, token: &str) -> PyResult<()> {
if let Some(mut trade) = self.active_trades.get_mut(token) {
if let Ok(market_data) = self.get_market_data(token.to_string()) {
trade.current_price = market_data.price;
trade.profit_loss = (market_data.price - trade.entry_price) / trade.entry_price * 100.0;

// Check take profit and stop loss
let settings = self.runtime.block_on(async { self.settings.read().await.clone() });
if trade.profit_loss >= settings.take_profit || trade.profit_loss <= settings.stop_loss {
trade.status = "CLOSING".to_string();
}
}
}
Ok(())
}
}

