import { Observable, Executable } from "../Kinds/Kinds";

type Noop = null | undefined | void;

type Hooks<E> =
| Observable<unknown, void, unknown>
| Executable<E | void, unknown>
| Noop;

const Render = <E extends unknown>(
thunk: () => E,
hooks: Hooks<E>[],
): E | void => {
let res: E;

try {
res = thunk();
} catch (err) {
console.error(err);
return;
}

const l = hooks.length;
const executables: Executable<E | void, unknown>[] = [];

const RUN_EFFECTS = (res: E) => {
const l = executables.length;
try {
for (let i = 0; i < l; i++) executables[i]?.ex(res);
} catch (err) {
console.error(err);
}
};

const RENDER = () => {
try {
const next = thunk();
if (next instanceof Node && res instanceof Node && res.parentNode) {
res.parentNode.replaceChild(next, res);
}
res = next;
} catch (err) {
console.error(err);
}
queueMicrotask(() => RUN_EFFECTS(res));
};

for (let i = 0; i < l; i++) {
const h = hooks[i]!;
if ("sub" in h && typeof h.sub === "function") {
h.sub(() => requestAnimationFrame(RENDER));
} else if ("ex" in h && typeof h.ex === "function") {
executables.push(h);
}
}

queueMicrotask(() => RUN_EFFECTS(res));

return res;
};

export { Render };

