(function ($) {
'use strict';

var DEBUG = false;

if (DEBUG) {
console.log('portfolio-list.js STARTING EXECUTION!');
}

// Store swiper instances to avoid multiple initializations
var swiperInstances = new Map();

function initPortfolioSwipers() {
var swiperContainers = $('.my-custom-portfolio-list.swiper'); // Updated selector

if (swiperContainers.length) {
swiperContainers.each(function () {
var $container = $(this);

// Prevent double initialization:
if (swiperInstances.has(this)) {
if (DEBUG) {
console.log('Swiper already initialized:', this);
}
return;
}

var swiperOptions = $container.data('swiper-options') || {};

// Fix navigation selectors by DOM elements, not strings:
if (swiperOptions.navigation && typeof swiperOptions.navigation === 'object') {
var nextEl = $container.find('.swiper-button-next')[0];
var prevEl = $container.find('.swiper-button-prev')[0];
if (nextEl && prevEl) {
swiperOptions.navigation.nextEl = nextEl;
swiperOptions.navigation.prevEl = prevEl;
} else {
// Disable if any missing, to prevent errors
swiperOptions.navigation = false;
}
}

// Fix pagination element similarly:
if (swiperOptions.pagination && typeof swiperOptions.pagination === 'object') {
var paginationEl = $container.find('.swiper-pagination')[0];
if (paginationEl) {
swiperOptions.pagination.el = paginationEl;
} else {
swiperOptions.pagination = false;
}
}

if (typeof Swiper !== 'undefined') {
var swiperInstance = new Swiper(this, swiperOptions);
swiperInstances.set(this, swiperInstance);

if (DEBUG) {
console.log('Swiper initialized on:', this);
console.log(swiperInstance);
}
} else if (DEBUG) {
console.warn('Swiper library not found. Please ensure it is enqueued.');
}
});
}
}

