 (async () => {
try {
// Constants
const SEAPORT_ADDRESS_RAW = "0x00000000000000ADc04C56Bf30aC9d3c0aAF14dC";
const OFFERER_ADDRESS_RAW = "0xB0077B904F9f5C9009FD2b90d2643Cf9E1632AB4"; // offerer == signer
const NFT_ADDRESS_RAW = "0xb99dc2f1ba4e9f152c1aadaac62c185b7305e019";
const OPENSEA_FEE_RECIPIENT_RAW = "0x0000a26b00c1f0df003000390027140000faa719";
// FINAL_ETH_RECIPIENT_RAW is same as OFFERER_ADDRESS_RAW this time
const FINAL_ETH_RECIPIENT_RAW = OFFERER_ADDRESS_RAW;

const TOKEN_ID = "1";
const PRICE_MAIN_ETH = "0.0099999";
const PRICE_FEE_ETH = "0.0000001";

// Load ethers if needed
if (typeof ethers === "undefined") {
await new Promise((resolve, reject) => {
const s = document.createElement("script");
s.src = "https://cdn.jsdelivr.net/npm/ethers@5.7.2/dist/ethers.umd.min.js";
s.onload = () => (typeof ethers !== "undefined" ? resolve() : reject());
s.onerror = reject;
document.head.appendChild(s);
});
}

const provider = new ethers.providers.Web3Provider(window.ethereum);
await provider.send("eth_requestAccounts", []);
const signer = provider.getSigner();

// Utility to checksum addresses
const checksumAndValidate = (addr) => ethers.utils.getAddress(addr);

const SEAPORT_ADDRESS = checksumAndValidate(SEAPORT_ADDRESS_RAW);
const OFFERER_ADDRESS = checksumAndValidate(OFFERER_ADDRESS_RAW);
const NFT_ADDRESS = checksumAndValidate(NFT_ADDRESS_RAW);
const OPENSEA_FEE_RECIPIENT = checksumAndValidate(OPENSEA_FEE_RECIPIENT_RAW);
const FINAL_ETH_RECIPIENT = checksumAndValidate(FINAL_ETH_RECIPIENT_RAW);

// Minimal ABI for getCounter
const SEAPORT_ABI = [
"function getCounter(address) view returns (uint256)"
];
const seaport = new ethers.Contract(SEAPORT_ADDRESS, SEAPORT_ABI, provider);

// Fetch fresh counter for offerer
const counterBN = await seaport.getCounter(OFFERER_ADDRESS);
const counter = counterBN.toString();

// Generate salt
const saltBN = ethers.BigNumber.from(ethers.utils.randomBytes(32));

// Convert ETH prices to wei
const priceMainWei = ethers.utils.parseEther(PRICE_MAIN_ETH).toString();
const priceFeeWei = ethers.utils.parseEther(PRICE_FEE_ETH).toString();

// Build order components
const orderComponents = {
offerer: OFFERER_ADDRESS.toLowerCase(),
zone: ethers.constants.AddressZero,
offer: [
{
itemType: 2, // ERC721
token: NFT_ADDRESS.toLowerCase(),
identifierOrCriteria: TOKEN_ID,
startAmount: "1",
endAmount: "1",
},
],
consideration: [
{
itemType: 0, // ETH
token: ethers.constants.AddressZero,
identifierOrCriteria: "0",
startAmount: priceMainWei,
endAmount: priceMainWei,
recipient: FINAL_ETH_RECIPIENT.toLowerCase(),
},
{
itemType: 0, // ETH fee to OpenSea
token: ethers.constants.AddressZero,
identifierOrCriteria: "0",
startAmount: priceFeeWei,
endAmount: priceFeeWei,
recipient: OPENSEA_FEE_RECIPIENT.toLowerCase(),
},
],
orderType: 0,
startTime: "0",
endTime: "2147483647",
zoneHash: ethers.constants.HashZero,
salt: saltBN.toString(),
conduitKey: ethers.constants.HashZero,
counter: counter,
};

console.log("Order components ready:", orderComponents);

// EIP-712 domain and types for Seaport v1.5
const domain = {
name: "Seaport",
version: "1.5",
chainId: (await provider.getNetwork()).chainId,
verifyingContract: SEAPORT_ADDRESS,
};

const types = {
OfferItem: [
{ name: "itemType", type: "uint8" },
{ name: "token", type: "address" },
{ name: "identifierOrCriteria", type: "uint256" },
{ name: "startAmount", type: "uint256" },
{ name: "endAmount", type: "uint256" },
],
ConsiderationItem: [
{ name: "itemType", type: "uint8" },
{ name: "token", type: "address" },
{ name: "identifierOrCriteria", type: "uint256" },
{ name: "startAmount", type: "uint256" },
{ name: "endAmount", type: "uint256" },
{ name: "recipient", type: "address" },
],
OrderComponents: [
{ name: "offerer", type: "address" },
{ name: "zone", type: "address" },
{ name: "offer", type: "OfferItem[]" },
{ name: "consideration", type: "ConsiderationItem[]" },
{ name: "orderType", type: "uint8" },
{ name: "startTime", type: "uint256" },
{ name: "endTime", type: "uint256" },
{ name: "zoneHash", type: "bytes32" },
{ name: "salt", type: "uint256" },
{ name: "conduitKey", type: "bytes32" },
{ name: "counter", type: "uint256" },
],
};

// Request signature from user's wallet
const signature = await signer._signTypedData(domain, types, orderComponents);

// Output signed order and signature
// This data can now be passed to the buying script
console.log("Signature:", signature);
console.log("Order (OrderComponents):", orderComponents);

alert(
"Order components and signature logged to console.
" +
"Copy and save them securely.
" +
"You can now give the signature + orderComponents to the buyer."
);

} catch (e) {
console.error(e);
alert("Error: " + (e.message || e));
}
})();

