// Helper for checksum addresses
const checksum = (addr) => ethers.utils.getAddress(addr);

// Seaport v1.5 contract address
const SEAPORT_ADDRESS = checksum("0x00000000000000ADc04C56Bf30aC9d3c0aAF14dC");

// Minimal ABI for fulfillAdvancedOrder method
const SEAPORT_ABI = [
