{ name: "signature", type: "bytes" },
{ name: "extraData", type: "bytes" },
],
outputs: [{ name: "fulfilled", type: "bool" }],
},
{
components: [
{ name: "orderIndex", type: "uint256" },
{ name: "side", type: "uint8" },
{ name: "index", type: "uint256" },
{ name: "identifier", type: "uint256" },
{ name: "criteriaProof", type: "bytes32[]" },
],
name: "criteriaResolvers",
type: "tuple[]",
},
{ name: "fulfillerConduitKey", type: "bytes32" },
{ name: "recipient", type: "address" },
],
},
];

const seaport = new ethers.Contract(SEAPORT_ADDRESS, SEAPORT_ABI, signer);

// Convert relevant fields to BigNumber instances for safe encoding
const bigNumberifyStr = (val) => ethers.BigNumber.isBigNumber(val) ? val : ethers.BigNumber.from(val);

// Prepare offers and considerations with BigNumber conversions + checksums:
const offer = orderComponents.offer.map((o) => ({
itemType: o.itemType,
token: checksum(o.token),
identifierOrCriteria: bigNumberifyStr(o.identifierOrCriteria),
startAmount: bigNumberifyStr(o.startAmount),
endAmount: bigNumberifyStr(o.endAmount),
}));

const consideration = orderComponents.consideration.map((c) => ({
itemType: c.itemType,
token: checksum(c.token),
identifierOrCriteria: bigNumberifyStr(c.identifierOrCriteria),
startAmount: bigNumberifyStr(c.startAmount),
endAmount: bigNumberifyStr(c.endAmount),
recipient: checksum(c.recipient),
}));

// Rebuild parameters tuple with converted types
const parameters = {
offerer: checksum(orderComponents.offerer),
zone: checksum(orderComponents.zone),
offer,
consideration,
orderType: orderComponents.orderType,
startTime: bigNumberifyStr(orderComponents.startTime),
endTime: bigNumberifyStr(orderComponents.endTime),
zoneHash: orderComponents.zoneHash,
salt: bigNumberifyStr(orderComponents.salt),
conduitKey: orderComponents.conduitKey,
totalOriginalConsiderationItems: consideration.length,
};

// Build advancedOrder object
const advancedOrder = {
parameters,
numerator: 1,
denominator: 1,
signature,
extraData: "0x",
};

// No criteria resolvers needed for typical cases
const criteriaResolvers = [];

// Usually, fulfiller uses zero conduit key
const fulfillerConduitKey = ethers.constants.HashZero;

// The receipt address is buyer by default but you can customize
const recipient = buyerAddress;

// Sum total ETH to pay (sum consideration items that are ETH = itemType 0)
const totalETH = consideration.reduce((acc, item) => {
if (item.itemType === 0) {
return acc.add(item.startAmount);
}
return acc;
}, ethers.BigNumber.from(0));

console.log("Total ETH to send (wei):", totalETH.toString());

// Submit order fulfillment transaction
const tx = await seaport.fulfillAdvancedOrder(
advancedOrder,
criteriaResolvers,
fulfillerConduitKey,
recipient,
{ value: totalETH }
);

console.log("Transaction submitted:", tx.hash);
alert(`Transaction sent! Hash:
${tx.hash}`);

const receipt = await tx.wait();

console.log("Transaction confirmed in block:", receipt.blockNumber);
alert(`Transaction confirmed! Block number: ${receipt.blockNumber}`);

} catch (err) {
console.error("Error:", err);
alert("Error: " + (err.message || err));
}
})();

