const result = {};
for (const key in obj) {
if (Object.prototype.hasOwnProperty.call(obj, key)) {
const val = obj[key];
if (typeof val === "string" && /^0x[a-fA-F0-9]{40}$/.test(val)) {
result[key] = val.toLowerCase();
} else {
result[key] = lowercaseAddresses(val);
}
}
}
return result;
}
return obj;
}
orderComponents = lowercaseAddresses(orderComponents);

// Debug logs, formatted nicely
console.log("Order components:", JSON.stringify(orderComponents, null, 2));
console.log("Counter:", counter);

const chainId = (await provider.getNetwork()).chainId;
const domain = {
name: "Seaport",
version: "1.5",
chainId,
verifyingContract: SEAPORT_ADDRESS,
};

// Sign typed data using offerer's private key wallet
const signature = await offererWallet._signTypedData(domain, EIP712_TYPES, orderComponents);

// Split and validate signature components per EIP-2 and OpenZeppelin standards
const { r, s, v } = ethers.utils.splitSignature(signature);
if (v !== 27 && v !== 28) throw new Error(`Invalid 'v' value in signature: ${v}`);

const SECP256K1_N = ethers.BigNumber.from(
"0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141"
);
const HALF_N = SECP256K1_N.div(2);
if (ethers.BigNumber.from(s).gt(HALF_N)) throw new Error("Signature 's' value is in upper range");

// Recover signer to verify signature correctness
const recovered = ethers.utils.verifyTypedData(domain, EIP712_TYPES, orderComponents, signature);
if (recovered.toLowerCase() !== OFFERER_ADDRESS.toLowerCase())
throw new Error("Signature rejected: signer mismatch");

console.log("Signature successfully verified.");

// Prepare advancedOrder param expected by fulfillAdvancedOrder
const advancedOrder = {
parameters: {
offerer: orderComponents.offerer,
zone: orderComponents.zone,
offer: orderComponents.offer,
consideration: orderComponents.consideration,
orderType: orderComponents.orderType,
startTime: orderComponents.startTime,
endTime: orderComponents.endTime,
zoneHash: orderComponents.zoneHash,
salt: orderComponents.salt,
conduitKey: orderComponents.conduitKey,
totalOriginalConsiderationItems: orderComponents.consideration.length,
},
numerator: 1,
denominator: 1,
signature,
extraData: "0x",
};

// Empty criteria resolvers for this order
const criteriaResolvers = [];
const fulfillerConduitKey = ethers.constants.HashZero;

// Calculate total ETH to send
const totalETH = orderComponents.consideration.reduce((acc, item) => {
if (item.itemType === 0) return acc.add(ethers.BigNumber.from(item.startAmount));
return acc;
}, ethers.BigNumber.from(0));

console.log(`Total ETH required: ${ethers.utils.formatEther(totalETH)}`);

if (!confirm(`Order signed. Send ${ethers.utils.formatEther(totalETH)} ETH to fulfill?`)) return;

// Send fulfillAdvancedOrder transaction
const tx = await seaport.fulfillAdvancedOrder(
advancedOrder,
criteriaResolvers,
fulfillerConduitKey,
BUYER_ADDRESS,
{ value: totalETH, gasLimit: 1500000 }
);
console.log("Transaction sent. Hash:", tx.hash);

await tx.wait();
alert("Order fulfillment successful!");
} catch (error) {
console.error(error);
alert(`Error: ${error.message || error}`);
}
