using System;
using System.Text.RegularExpressions;

public class ValuesBasedOnString
{
// Thresholds constants
private const int ShortCharThreshold = 20;
private const int ShortWordThreshold = 4;
private const int LongCharThreshold = 100;
private const int LongWordThreshold = 15;

private readonly Random _rnd = new Random();

/// <summary>
/// The original input string.
/// </summary>
public string Input { get; }

/// <summary>
/// The processed string with commas replaced by newlines (if applicable).
/// </summary>
public string FormattedSpeak { get; private set; }

/// <summary>
/// The calculated quality value based on the input string.
/// </summary>
public int Quality { get; private set; }

/// <summary>
/// The calculated duration value based on the input string.
/// </summary>
public int Duration { get; private set; }

/// <summary>
/// The generated mix line in the format expected: "[verse]
{ProcessedSpeak}"
/// </summary>
public string MixLine => "[verse]" + Environment.NewLine + FormattedSpeak;

/// <summary>
/// Constructor, takes the input text and calculates values.
/// </summary>
/// <param name="input">The speech input string.</param>
public ValuesBasedOnString(string input)
{
Input = input ?? string.Empty;
ProcessInput();
}

/// <summary>
/// Processes the input string and sets Quality, Duration, and FormattedSpeak properties.
/// </summary>
private void ProcessInput()
{
int charLength = Input.Length;
int wordCount = Input.Split(new char[] { ' ', '	', '
' }, StringSplitOptions.RemoveEmptyEntries).Length;

if (Input.Contains(","))
{
// If commas are present, fixed values and replace commas with newlines
Quality = 20;
Duration = 27;

FormattedSpeak = Regex.Replace(Input, @",\s*", Environment.NewLine);
}
else
{
FormattedSpeak = Input;

if (charLength <= ShortCharThreshold || wordCount <= ShortWordThreshold)
{
// Very short sentence
Quality = 11;
Duration = 5;
}
else if (charLength >= LongCharThreshold || wordCount >= LongWordThreshold)
{
// Long or complex sentence - randomize within range
Quality = _rnd.Next(15, 28); // 15 to 27 inclusive
Duration = _rnd.Next(15, 28); // 15 to 27 inclusive
}
else
{
// Medium length sentence
Quality = 11;
Duration = 5;
}
}
}
}

