const overlay = document.getElementById('new-header-menu-overlay');

function closeMenu() {
hamburger.setAttribute('aria-expanded', 'false');
nav.classList.remove('new-header-active');
overlay.classList.remove('new-header-active');
}

hamburger.addEventListener('click', () => {
const expanded = hamburger.getAttribute('aria-expanded') === 'true';
if(expanded) {
closeMenu();
} else {
hamburger.setAttribute('aria-expanded', 'true');
nav.classList.add('new-header-active');
overlay.classList.add('new-header-active');
}
});

// Auto close mobile menu on menu link click
document.querySelectorAll('#new-header-nav a').forEach(link => {
link.addEventListener('click', () => {
if(window.innerWidth <= 768){
closeMenu();
}
});
});

// Close menu if clicking outside menu (on overlay)
overlay.addEventListener('click', closeMenu);

// Optional: close menu on ESC key
document.addEventListener('keydown', e => {
if(e.key === 'Escape') {
if(nav.classList.contains('new-header-active')) {
closeMenu();
}
}
});

})();
</script>
